REPLACE INTO ?:page_descriptions (page_id, page, description, lang_code) VALUES('9', 'Ergom (страница продавца)', '<p>Страница продавца бренда Ergom. На ней размещён ассортимент, который поставляет этот продавец, и она служит точкой входа в каталог производителей.</p><!--CUT--><p><b>Что размещено на странице:</b><ul><li>Позиции, поставляемые продавцом.</li><li>Краткое описание бренда и его места в каталоге.</li></ul>', 'ru');
REPLACE INTO ?:page_descriptions (page_id, page, description, lang_code) VALUES('10', 'Ergom PRO (страница продавца)', '<p>Страница продавца линейки Ergom PRO. Страница привязана к продавцу и показывает только товары этого производителя.</p><!--CUT--><p>Список производителей на витрине строится из страниц этого типа, поэтому каждому бренду продавца соответствует своя запись в каталоге.</p>', 'ru');
